use super::*;

/// Records that HOLD more than one extractable leaf but are DEMOTED as cohesive (leave whole) — id +
/// the reason — so `bsc graph methods` can show what it declined to flag and why, and the inflated raw
/// count is visible beside the genuine one.
pub fn demoted(impls: &[Value]) -> Vec<(String, String)> {
    let mut out: Vec<(String, String)> = impls
        .iter()
        .filter(|r| is_candidate_record(r))
        .filter_map(|r| {
            let id = r.get("id").and_then(Value::as_str)?.to_string();
            let code = r.get("code").and_then(Value::as_str).unwrap_or("");
            let tech = r.get("tech").and_then(Value::as_str).unwrap_or("");
            let names = extractable_leaves(code, tech);
            if names.len() <= 1 {
                return None;
            }
            cohesion_reason(code, tech, &names).map(|why| (id, why))
        })
        .collect();
    out.sort_by(|a, b| a.0.cmp(&b.0));
    out
}
